#include <vector>
#include <queue>
#include <climits>

using namespace std;

class Solution {
public:
    int minimumDeviation(vector<int>& nums) {
        priority_queue<int> pq;
        int minVal = INT_MAX;
        for (int& n : nums) {
            if (n % 2 == 1) n *= 2;
            pq.push(n);
            minVal = min(minVal, n);
        }

        int res = INT_MAX;
        while (!pq.empty()) {
            int maxVal = pq.top(); pq.pop();
            res = min(res, maxVal - minVal);
            if (maxVal % 2 == 0) {
                maxVal /= 2;
                minVal = min(minVal, maxVal);
                pq.push(maxVal);
            } else break;
        }
        return res;
    }
};
